def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_pressure = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > budget:
                    rich_pressure = max(rich_pressure, float(bid))

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    low_supply = supply <= 17
    high_supply = supply >= 22
    desperate = (no_water_days >= 2) or (hp <= 3)
    urgent = (no_water_days >= 1 and hp <= 5)

    if desperate:
        target = max(DAILY_SALARY * 1.05, highest_prev + 3.0)
        if low_supply:
            target += 8.0
        return float(min(budget, target))

    if urgent:
        target = max(DAILY_SALARY * 0.8, highest_prev * 0.72 + 4.0)
        if low_supply:
            target += 6.0
        return float(min(budget, target))

    if highest_prev >= 140:
        if hp >= 7 and no_water_days == 0:
            target = DAILY_SALARY * 0.18
        else:
            target = DAILY_SALARY * 0.58
        if low_supply:
            target += 5.0
        return float(min(budget, target))

    if highest_prev >= 90:
        target = max(DAILY_SALARY * 0.42, avg_prev * 0.42)
        if low_supply:
            target += 6.0
        elif high_supply:
            target -= 4.0
        return float(min(budget, max(0.0, target)))

    target = DAILY_SALARY * 0.34
    if low_supply:
        target += 7.0
    if high_supply:
        target -= 5.0
    if rich_pressure > 100:
        target -= 3.0
    if hp >= 8 and no_water_days == 0 and day <= 3:
        target -= 3.0

    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    # If no one else, bid to secure water efficiently
    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.45)

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Read yesterday trace bids to infer aggressiveness
    yesterday_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev

    # Supply pressure: with supply in [15,25], max water units roughly 15/9..25/9.
    # Lower supply means fewer total units, so increase bid to avoid losing.
    scarcity = 0.0
    if supply <= 17.0:
        scarcity = 1.0
    elif supply <= 20.0:
        scarcity = 0.6
    else:
        scarcity = 0.25

    # Opponent aggression indicator: Cindy survived with very high bids yesterday.
    # If highest_prev is large relative to our salary, assume strong continuation.
    aggressive = 1.0 if highest_prev >= DAILY_SALARY * 1.2 else 0.0

    # Base target bid
    # - If aggressive: slightly overbid the likely second-highest to secure.
    # - If not aggressive: bid around midrange.
    if aggressive > 0.5:
        target = max(second_prev + 2.0, DAILY_SALARY * (0.55 + 0.25 * scarcity))
    else:
        target = DAILY_SALARY * (0.45 + 0.25 * scarcity)

    # If my HP is low, I must secure water more urgently
    if my_hp <= 2.0:
        target *= 1.6
    elif my_hp <= 4.0:
        target *= 1.25

    # Budget cap and non-negative
    if my_budget <= 0.0:
        return 0.0

    bid = min(my_budget, target)

    # Avoid bidding too tiny amounts when supply is scarce
    min_bid = 2.0 if scarcity <= 0.25 else 8.0
    if bid < min_bid:
        bid = min(my_budget, min_bid)

    # Final clamp to a reasonable upper bound (can't exceed budget anyway)
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not prev_bids:
        base_bid = DAILY_SALARY * 0.4
    else:
        avg_prev = sum(prev_bids) / len(prev_bids)
        base_bid = min(avg_prev * 1.05, DAILY_SALARY * 0.9)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.1)

    if supply < WATER_REQ * 1.5:
        return min(my_status['budget'], base_bid * 1.2)

    return min(my_status['budget'], base_bid * 0.8)

